    this._applyBtn = h('button', { type: 'button', class: 'o-btn o-btn-primary o-btn-sm' }, icon('check', { size: 16 }), h('span', null, this.t('docScanner.addPage')));
    on(this._applyBtn, 'click', () => this.applyCorners());
