      if (label) { const l = CE.next('text', 'o-ch-caption'); chSetText(l, chFit(label, r0 * 1.5, ch.font(400))); chAttr(l, { x: cx, y: r1(cy + vf * 0.62), 'text-anchor': 'middle', 'dominant-baseline': 'central' }); }
