        const w = cw - gap, hh = chh - gap;
        el.setAttribute('d', chRectPath(x0 + cw * i + gap / 2 + (w * (1 - te)) / 2, y0 + chh * j + gap / 2 + (hh * (1 - te)) / 2, w * te, hh * te, Math.min(3, w / 4)));
        el.dataset.i = i; el.dataset.j = j;
