    bubbles.forEach((b, n) => order.push({ t: 'b', i: n }));
    const aOf = n => (order[n].t === 'r' ? { s: -1, i: order[n].i, n } : { s: bubbles[order[n].i].s.key, i: order[n].i, b: true, n });
