    this._padY = parseFloat(cs.paddingTop) || 0;
    this._padX = parseFloat(cs.paddingRight) || 0;
    const probe = h('span', { class: 'o-ce-probe' }, 'x'.repeat(100));
    this.pre.append(probe);
