        if (!g) { g = this._gslots[k] = { el: h('div', { class: 'o-ce-ln' }), key: '' }; this.gutterInner.appendChild(g.el); }
        const key = i + '|' + (i === act ? 1 : 0) + '|' + (errs ? errs[0].severity : '');
