    const ly = chipY - 6;
    lines.forEach((ln, i) => label.append(svg('tspan', { x: dgF(tx), y: dgF(ly + i * 15), dy: '0.35em' }, ln)));
    g.append(label);
    g.append(svg('text', { class: 'o-wf-sub', x: dgF(tx), y: dgF(chipY + 12) }, ctx.host.t('workflow.types.' + type)));
