  on(list, 'click', '.o-ek-item', (e, b) => choose(b));
  on(list, 'keydown', e => { if (e.key === 'Tab') { e.preventDefault(); pop.close('tab'); return; } nav.handle(e); });
  on(list, 'mousemove', '.o-ek-item', (e, b) => { if (doc.activeElement !== b) nav.setItem(b, { scroll: false }); });
